steps.solution:
import numpy as np

def nearest(query, items):
    q = np.array(query, dtype=float)
    best_name, best_dist = None, None
    for name, vec in items.items():
        d = float(np.sum((np.array(vec, dtype=float) - q) ** 2) ** 0.5)
        if best_dist is None or d < best_dist:
            best_name, best_dist = name, d
    return best_name
